// src/components/Controls.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import './Controls.css';

export default function Controls({
  provinces,
  selectedProvinces,
  onChangeProvinces,
  foodTypes,
  selectedFoodType,
  onChangeFoodType,
  dateRange,
  onChangeDateRange
}) {
  const { t } = useTranslation();

  // Show loading until data arrives
  if (!foodTypes.length || !provinces.length) {
    return <p>Loading...</p>;
  }

  const handleProvinceToggle = prov => {
    const newSelection = selectedProvinces.includes(prov)
      ? selectedProvinces.filter(p => p !== prov)
      : [...selectedProvinces, prov];
    onChangeProvinces(newSelection);
  };

  return (
    <div className="controls-container">
      <div className="control-group">
        <label htmlFor="food-type-select">{t('select_food_type')}</label>
        <select
          id="food-type-select"
          className="select"
          value={selectedFoodType}
          onChange={e => onChangeFoodType(e.target.value)}
        >
          <option value="" disabled>
            -- {t('select_food_type')} --
          </option>
          {foodTypes.map(type => (
            <option key={type} value={type}>
              {type}
            </option>
          ))}
        </select>
      </div>

      <div className="control-group">
        <span>{t('select_provinces')}</span>
        <div className="checkbox-group">
          {provinces.map(prov => (
            <label key={prov}>
              <input
                type="checkbox"
                checked={selectedProvinces.includes(prov)}
                onChange={() => handleProvinceToggle(prov)}
              />
              {prov}
            </label>
          ))}
        </div>
      </div>

      <div className="control-group">
        <label htmlFor="start-month">{t('select_date_range')}</label>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <input
            id="start-month"
            className="date-input"
            type="month"
            value={dateRange.start}
            onChange={e => onChangeDateRange({ ...dateRange, start: e.target.value })}
          />
          <span>–</span>
          <input
            id="end-month"
            className="date-input"
            type="month"
            value={dateRange.end}
            onChange={e => onChangeDateRange({ ...dateRange, end: e.target.value })}
          />
        </div>
      </div>
    </div>
  );
}
